var routes = {
  'alarm': 'tb.nic.candidate.alarm.v1',
  'device_state': 'tb.nic.candidate.device-state.v1',
  'lifecycle': 'tb.nic.candidate.lifecycle.v1',
  'ota': 'tb.nic.candidate.ota.v1'
};
var candidateType = msg['candidateType'];
if (candidateType == null) { throw new Error('missing_candidate_type'); }
var topic = routes[candidateType];
if (topic == null) { throw new Error('unknown_candidate_type:' + candidateType); }
metadata['kafkaTopic'] = topic;
return {msg: msg, metadata: metadata, msgType: msgType};
